import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May 23:59:59.999 UTC is the last instant

log = lambda *a: print(*a, file=sys.stderr, flush=True)


class Client:
    def __init__(self):
        self.token = None
        self.get_token()

    def get_token(self):
        req = urllib.request.Request(BASE + "/token", method="POST")
        body = self.raw(req)
        self.token = body["token"]
        log("token refreshed:", self.token)

    def raw(self, req):
        """Single request with retry for 429 / 5xx / connection errors. Returns parsed JSON or raises HTTPError for 4xx other than 401."""
        attempts = 0
        while True:
            attempts += 1
            try:
                with urllib.request.urlopen(req, timeout=30) as r:
                    return json.loads(r.read().decode("utf-8"))
            except urllib.error.HTTPError as e:
                payload = e.read().decode("utf-8", "replace")
                if e.code == 429:
                    wait = e.headers.get("Retry-After")
                    log("429 from", req.full_url, "Retry-After:", wait, "body:", payload[:200])
                    time.sleep(float(wait) if wait else 5)
                    continue
                if 500 <= e.code < 600:
                    log("HTTP", e.code, "from", req.full_url, payload[:200], "- retrying")
                    time.sleep(min(2 ** attempts, 30))
                    continue
                raise
            except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
                log("connection error", req.full_url, repr(e), "- retrying")
                time.sleep(min(2 ** attempts, 30))
                continue

    def authed_get(self, path):
        """GET with bearer token; on 401 refresh token once per call and retry."""
        for _ in range(5):
            req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + self.token})
            try:
                return self.raw(req)
            except urllib.error.HTTPError as e:
                if e.code == 401:
                    log("401 on", path, "- refreshing token")
                    self.get_token()
                    continue
                if e.code == 404:
                    return None
                raise
        raise RuntimeError("too many auth failures on " + path)


def parse_ts(s):
    dt = datetime.fromisoformat(s)  # handles Z and +hh:mm on Python 3.11
    if dt.tzinfo is None:
        raise ValueError("timestamp without offset: " + s)
    return dt.astimezone(timezone.utc)


def round_half_up_div(n, d):
    # n, d integers, d > 0; returns round-half-up of n/d for n >= 0
    return (2 * n + d) // (2 * d)


def main():
    client = Client()

    # --- Pull all order pages, following "next" and checking against total_pages ---
    listings = []  # every listing, in order received
    pages_seen = []
    path = "/orders?page=1"
    total_pages = None
    while path:
        data = client.authed_get(path)
        page_no = data["page"]
        if total_pages is None:
            total_pages = data["total_pages"]
        log(f"page {page_no}/{data['total_pages']} items={len(data['items'])} next={data['next']}")
        pages_seen.append(page_no)
        listings.extend(data["items"])
        path = data["next"]

    expected = list(range(1, total_pages + 1))
    if sorted(pages_seen) != expected:
        raise SystemExit(f"page coverage mismatch: got {sorted(pages_seen)}, expected 1..{total_pages}")

    # --- Dedupe by order id ---
    by_id = {}
    duplicates_skipped = 0
    conflicting = []
    for o in listings:
        oid = o["id"]
        if oid in by_id:
            duplicates_skipped += 1
            if by_id[oid] != o:
                conflicting.append((by_id[oid], o))
        else:
            by_id[oid] = o
    log(f"listings={len(listings)} distinct={len(by_id)} duplicates_skipped={duplicates_skipped} conflicting_dupes={len(conflicting)}")
    for a, b in conflicting[:5]:
        log("  CONFLICT:", a, "vs", b)

    # --- Filter and compute ---
    statuses = {}
    qualifying = []
    customer_ids = set()
    for o in by_id.values():
        statuses[o["status"]] = statuses.get(o["status"], 0) + 1
        if o["status"] != "shipped":
            continue
        ts = parse_ts(o["placed_at"])
        if not (RANGE_START <= ts < RANGE_END):
            continue
        qualifying.append((o, ts))
        customer_ids.add(o["customer_id"])
    log("status counts (all distinct orders):", statuses)
    log(f"qualifying orders: {len(qualifying)}; distinct customers: {len(customer_ids)}")

    # --- Customers, each looked up once ---
    customers = {}
    for cid in sorted(customer_ids):
        c = client.authed_get("/customers/" + cid)
        if c is None:
            raise SystemExit(f"customer {cid} returned 404")
        customers[cid] = c

    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    for o, ts in qualifying:
        c = customers[o["customer_id"]]
        pct = c["discount_pct"]
        if not isinstance(pct, int) or not (0 <= pct <= 100):
            raise SystemExit(f"odd discount_pct for {c['id']}: {pct!r}")
        amt = o["amount_cents"]
        if not isinstance(amt, int):
            raise SystemExit(f"non-integer amount for {o['id']}: {amt!r}")
        discounted = round_half_up_div(amt * (100 - pct), 100)
        total += discounted
        region = c["region"]
        if region not in by_region:
            raise SystemExit(f"unknown region {region!r} for {c['id']}")
        by_region[region] += discounted

    assert sum(by_region.values()) == total

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

